<template>
  <q-card
    flat
    class="page-background"
    :class="
      createTaskPopup || editTaskPopup ? 'no-background-color backdrop ' : ''
    "
  >
    <div class="row items-center no-wrap items-center q-ma-xs">
      <span class="secondary-c-text text-h6 text-weight-bold label-text">
        {{ $t('tasks') }}
      </span>

      <f-btn
        flat
        round
        dense
        appearance="tertiary"
        icon="close"
        @click="$emit('btnClicked')"
        class="margin-left-auto"
      />
    </div>

    <q-separator class="separator-space" />

    <q-card-section class="tasks-container-padding">
      <div class="row full-width items-center">
        <div class="row full-width items-center selectable">
          <q-btn
            icon="add_task"
            class="cursor-pointer link-color no-padding-left-right"
            flat
            @click="
              createTaskPopup = true;
              editTaskPopup = false;
            "
          >
          </q-btn>
          <label
            @click="
              createTaskPopup = true;
              editTaskPopup = false;
            "
            class="q-ml-sm cursor-pointer link-color"
            >{{ $t('add_a_task') }}</label
          >
        </div>

        <template
          v-for="(record, index) in document_related_tasks"
          :key="index"
        >
          <div class="full-width pa-2">
            <div class="full-width back-white border-radius-5px">
              <div class="row items-center no-wrap items-center">
                <f-btn
                  class="p-4"
                  appearance="flat"
                  @click="updateStatus(index, record)"
                  :icon="record.done_task_icon"
                  v-on:mouseover="changeIconForOver(index, record)"
                  v-on:mouseout="changeIconForOut(index, record)"
                >
                  <q-tooltip>
                    <template v-if="record.status == 'done'">
                      {{ $t('mark_as_open') }}
                    </template>
                    <template v-else>
                      {{ $t('mark_as_done') }}
                    </template>
                  </q-tooltip>
                </f-btn>

                <label
                  class="text-ellipsis cursor-pointer full-width q-mr-sm label-text"
                  @click="goToDetail(record.id)"
                  >{{ record.title }}</label
                >

                <q-btn flat dense round @click.stop.prevent icon="more_vert">
                  <q-menu
                    style="min-width: 140px"
                    auto-close
                    transition-show="jump-down"
                    transition-hide="jump-up"
                    anchor="bottom middle"
                    self="top middle"
                  >
                    <q-list dense>
                      <!-- <q-item clickable>
                            <q-item-section @click="editRecord(index, record)">
                                <span>
                                  {{$t('edit')}}
                                </span>
                              </q-item-section>
                          </q-item> -->
                      <q-item clickable>
                        <q-item-section @click="updateStatus(index, record)">
                          <span>
                            <template v-if="record.status == 'done'">
                              {{ $t('mark_as_open') }}
                            </template>
                            <template v-else>
                              {{ $t('mark_as_done') }}
                            </template>
                          </span>
                        </q-item-section>
                      </q-item>
                      <q-separator v-if="canDeleteTask(record)" inset />
                      <q-item v-if="canDeleteTask(record)" clickable>
                        <q-item-section @click="deleteRecord(index, record)">
                          <span class="text-red">
                            {{ $t('delete') }}
                          </span>
                        </q-item-section>
                      </q-item>
                    </q-list>
                  </q-menu>
                </q-btn>
              </div>

              <div class="row text-grey-6 font-size-0-65 items-center">
                <q-icon name="person" size="xs" class="q-pr-xs q-pl-xs">
                  <q-tooltip> {{ $t('assignee') }} </q-tooltip>
                </q-icon>
                <span>{{
                  record.assigned_to_user
                    ? record.assigned_to_user
                    : record.assigned_to_group
                }}</span>
              </div>
            </div>
          </div>
        </template>
      </div>
    </q-card-section>
  </q-card>

  <div class="row full-width task-sidebar-pagination">
    <q-pagination
      v-if="total_pages > 1"
      v-model="current_page"
      :max="total_pages"
      :max-pages="6"
      direction-links
      unelevated
      color="black"
      active-color="black"
      class="doc2-pagination q-ml-auto q-mr-auto"
      @click="nexPageClicked()"
    ></q-pagination>
  </div>

  <div class="popup-container" v-if="createTaskPopup || editTaskPopup">
    <div class="popup">
      <Create
        v-if="createTaskPopup"
        @closeCreatePopup="createTaskPopup = false"
        @refreshTasks="refreshTasks"
      />

      <ShortEdit
        v-if="editTaskPopup"
        @closeCreatePopup="resetEditPopup"
        :selected_record="selected_record"
        @refreshTasks="refreshTasks"
      />
    </div>
  </div>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import {
  useDropdownStore,
  useGroupDropdownStore,
  useDocumentStore,
  useTaskStore,
  useSettingStore,
} from 'src/store/main';
import Create from './Create.vue';
import ShortEdit from './ShortEdit.vue';
import { taskApiService } from 'src/services';
import { notify } from 'src/components/notifications/notify';
import { isUserAdmin } from 'src/utils/UserDetails';
import { canDeleteTaskRow } from 'src/utils/taskDeletePermission';
import { tasks_non_admin_delete_permission_setting } from 'src/constants';

export default defineComponent({
  props: {},
    emits: ['btnClicked'],

  watch: {
    doc_loaded: {
      handler: function (newVal, oldVal) {
        this.initView();
      },
    },
  },
  components: {
    Create,
    ShortEdit,
  },
  data() {
    return {};
  },
  mounted: function () {
    this.initView();
  },
  methods: {
    async initView() {
      try {
        this.processing = true;
        await this.prepareUsersDropdown();
        await this.getGroups();
        if (!this.data_fetched) {
          await this.fetchTasks();
        }
        if (this.data_fetched) {
          this.formatTasks();
          this.setPagination();
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
      }
    },

    async fetchTasks() {
      try {
        this.processing = true;
        const params: dynamicObj = {};
        if (this.record && this.record.doc_id) {
          params['document_id'] = this.record.doc_id;
        }
        params['status'] = 'open,in_progress';

        await this.getTasks(params);
        this.formatTasks();
        this.setPagination();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
      }
    },

    formatTasks() {
      for (const [key, item] of Object.entries(this.document_related_tasks)) {
        const task = item as any;
        const task_index = Number(key);

        task.done_task_icon = 'radio_button_unchecked';
        if (task.status === 'done') {
          task.done_task_icon = 'done';
        }

        this.document_related_tasks[task_index] = task;
      }
    },

    setPagination() {
      if (this.total_document_tasks > 0) {
        this.setTotalPages();
      }
    },

    refreshTasks() {
      notify.success(this.$t('MSG_SAVE'));
      this.resetPagination();
      this.fetchTasks();
    },

    async deleteRecord(index: number, record: dynamicObj) {
      try {
        this.processing = true;
        const response = await taskApiService.deleteTask(record.id);
        if (response.success === false) {
          throw response;
        }

        this.document_related_tasks.splice(index, 1);
        this.document_related_tasks = this.document_related_tasks.filter(
          (x: dynamicObj) => {
            return x.id !== record.id;
          },
        );
        this.total_document_tasks = this.total_document_tasks - 1;
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
      }
    },

    changeIconForOver(index: number, record: dynamicObj) {
      let new_icon = 'done';
      if (record.status === 'done') {
        new_icon = 'radio_button_unchecked';
      }

      this.document_related_tasks[index].done_task_icon = new_icon;
    },

    changeIconForOut(index: number, record: dynamicObj) {
      let new_icon = 'radio_button_unchecked';
      if (record.status === 'done') {
        new_icon = 'done';
      }
      this.document_related_tasks[index].done_task_icon = new_icon;
    },

    async updateStatus(index: number, record: dynamicObj) {
      try {
        this.processing = true;
        const data: dynamicObj = {};

        data['status'] = 'done';
        if (record.status === 'done') {
          data['status'] = 'open';
        }
        logInfo(data);
        const response = await taskApiService.updateTask(record.id, data);
        if (response.success === false) {
          throw response;
        }

        if (data['status'] === 'done') {
          this.removeDoneTask(index);
          return;
        }

        this.fetchTasks();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
      }
    },

    removeDoneTask(index: number) {
      this.document_related_tasks.splice(index, 1);
      this.total_document_tasks = Math.max(0, this.total_document_tasks - 1);
      this.decreaseOpenTaskCount(1);
    },

    editRecord(index: number, record: dynamicObj) {
      this.selected_record = record;
      this.editTaskPopup = true;
      this.createTaskPopup = false;
    },

    resetEditPopup() {
      this.selected_record = {} as dynamicObj;
      this.editTaskPopup = false;
    },

    resetPagination() {
      this.total_pages = 0;
      this.current_page = 1;
      this.total_document_tasks = 0;
      this.offset = 0;
    },

    setTotalPages() {
      this.total_pages = Math.ceil(this.total_document_tasks / this.page_size);
    },

    calculateOffset() {
      this.offset = this.page_size * (this.current_page - 1);
    },

    async nexPageClicked() {
      try {
        this.calculateOffset();
        await this.fetchTasks();
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },

    goToDetail(id: string) {
      (<any>window).open('/task/' + id, '_blank').focus();
    },

    canDeleteTask(record: dynamicObj): boolean {
      return canDeleteTaskRow({
        isAdmin: isUserAdmin(),
        permission:
          this.org_based_settings[tasks_non_admin_delete_permission_setting],
        taskCreatedBy: record.created_by,
        currentUserId: this.userId,
        taskBelongsToSomeoneElse: this.isHasAccess(record),
      });
    },
  },

  setup() {
    const doc_store = useDocumentStore();
    const { record } = storeToRefs(doc_store);

    const settings_store = useSettingStore();
    const { org_based_settings } = storeToRefs(settings_store);

    const dropdown_store = useDropdownStore();
    const { prepareUsersDropdown } = dropdown_store;

    const group_dropdown_store = useGroupDropdownStore();
    const { getGroups } = group_dropdown_store;

    const task_store = useTaskStore();
    const {
      document_related_tasks,
      tasks_loading,
      total_document_tasks,
      data_fetched,
      offset,
      page_size,
      userId,
    } = storeToRefs(task_store);
    const { getTasks, decreaseOpenTaskCount, isHasAccess } = task_store;

    return {
      data_fetched,
      total_document_tasks,
      document_related_tasks,
      tasks_loading,
      getTasks,
      decreaseOpenTaskCount,
      isHasAccess,
      userId,
      org_based_settings,
      record,
      getGroups,
      prepareUsersDropdown,
      createTaskPopup: ref(false),
      processing: ref(false),

      selected_record: ref({} as dynamicObj),
      editTaskPopup: ref(false),

      current_page: ref(1),
      total_pages: ref(0),
      offset,
      page_size,
    };
  },
});
</script>

